const out = [];
for (const p of $json.portfolio) {
  out.push({ json: { simbol: p.simbol, chain: p.chain, pair: p.pair, jumlah: p.jumlah } });
}
return out;

const pair = $json.pair || $json.pairs?.[0] || {};
const simbol = $('Pecah Per Aset').item.json.simbol;
const jumlah = $('Pecah Per Aset').item.json.jumlah;

const harga = parseFloat(pair.priceUsd || 0);
const nilai = harga * jumlah;
const chg = parseFloat(pair.priceChange?.h24 || 0);
const liq = parseFloat(pair.liquidity?.usd || 0);
const vol = parseFloat(pair.volume?.h24 || 0);

return [{
  json: {
    simbol, jumlah, harga, nilai,
    change_24h: chg, liquidity: liq, volume_24h: vol,
    tanggal: new Date().toISOString().slice(0, 10)
  }
}];

// Gabung semua aset jadi 1 laporan
const items = $input.all();
let total = 0;
let pesan = '📈 *LAPORAN PORTFOLIO HARIAN*\n';
pesan += 'Tanggal: ' + items[0].json.tanggal + '\n';
pesan += '━━━━━━━━━━━━━━━━━━\n\n';

for (const it of items) {
  const j = it.json;
  total += j.nilai;
  const tanda = j.change_24h >= 0 ? '📈' : '📉';
  pesan += tanda + ' *' + j.simbol + '*\n';
  pesan += '   Jumlah: ' + Number(j.jumlah).toLocaleString('en-US') + '\n';
  pesan += '   Harga: $' + Number(j.harga).toPrecision(6) + '\n';
  pesan += '   Nilai: $' + j.nilai.toFixed(2) + '\n';
  pesan += '   24j: ' + j.change_24h.toFixed(2) + '%\n\n';
}

pesan += '━━━━━━━━━━━━━━━━━━\n';
pesan += '💰 *TOTAL NILAI: $' + total.toFixed(2) + '*';

return [{ json: { laporan: pesan, total_nilai: total } }];
